INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2937, 'itIT', 'Li ho osservati mentre lo picchiavano selvaggiamente. Il loro tenente si comportava come se un simile atto di crudeltà fosse una cosa normale. Alla vista di quel pestaggio, non ho resistito.$B$BMentre il Vendicatore Saruan incassava i loro colpi, ho cominciato a piangere. Non erano lacrime di paura, ma di tristezza nel vedere un Draenei del Triumvirato trattato in quel modo. Se solo mi fossi potuto liberare dalle mie catene...', 0),
(2938, 'itIT', 'Dopo quella che sembrò un''eternità, il Vendicatore perse conoscenza. La tortura era stata troppo violenta, anche per lui. Il tipo crudele, che poi ho scoperto chiamarsi Matis, tentò di risvegliare Saruan gettandogli addosso dell''acqua corrotta sul suo corpo devastato. Ma Saruan non reagì.', 0),
(2939, 'itIT', 'Volevo urlare, ma dalla mia bocca uscì a malapena un sospiro. Fui subito picchiato per quest''atto di ribellione. Mentre ero steso a terra, vedevo Matis visibilmente agitato mentre faceva avanti e indietro di fronte al corpo di Saruan. Disse che Sironas, o Sirona, o un''entità con un nome simile, gli avrebbe strappato la carne dalle ossa se Saruan fosse morto durante la tortura.', 0),
(2940, 'itIT', 'Disse che quell''entità di nome Sironas aveva dei progetti per Saruan...$B$B<La scrittura si interrompe bruscamente e una lunga linea riempie il resto della pagina. Questo Draenei è morto mentre stava scrivendo.>', 0),
(3279, 'itIT', 'Servitori, ascoltate la chiamata del padrone! Il Re dei Lich ha dato a Drakuru il controllo di tutte quante le armate del Flagello a Zul''drak. Teniamo l''ordine di accidere tutti quanti!$B$BDEVONO SCHIATTARE TUTTI QUANTI!$B$BImpacchetteremo tutti quanti i cadaveri nei Campi Sterili e li manderemo ai guaglioni del Principe Navarius a Zeramas, perché diventino parte del Flagello! Sotto il comando di Drakuru nun si spreca niente!$B$BPresto berremo il sangue dei profeti e diventeremo più forti che mai! Zul''drak e Gundrak cadranno sotto il Flagello!', 0),
(3280, 'itIT', 'Molto tempo fa, quando solo il Vento del Nord sibilava fra questi picchi, il fratello di un potente Condottiero Taunka bramava queste terre.', 0),
(3281, 'itIT', 'Il fratello del Condottiero, Zoccolo Tempestoso, raccolse le proprie forze e partì, con l''intento di strappare le Cime Tempestose al loro legittimo sovrano, il Vento del Nord.', 0),
(3605, 'itIT', 'Dedicato a tutti coloro che sono caduti per mano del Flagello durante la guerra nelle Distese Ghiacciate.', 0);
